        address poolInitializer,
        address launcher,
        bytes32 tickerKey,
        uint48 deployedAt,
        uint48 reservedUntil,
        string normalizedTicker
    );
    /// @notice Emitted once per launch, immediately BEFORE {LaunchCreated} in the same transaction (lower
