    function setRequiredPoolInitializer(address poolInitializer) external;
    function setLegacyLauncher(address launcher) external;
    function setReservationDuration(uint48 duration) external;
    function setTickerExpiry(string calldata ticker, uint48 reservedUntil) external;
    function pause() external;
    function unpause() external;
    function sweepNative(address payable recipient, uint256 amount) external;
    function sweepERC20(address token, address recipient, uint256 amount) external;
}
